"""Snapshot this LOW run without staging other colleagues' dirty records."""
import copy,hashlib,json,os,re,subprocess,sys,time
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from PIL import Image
from tools.common import ROOT,read_json,write_json,file_sha256,machine_id,utc_now
from mod_nailong.tools.master_files import sync_git,master_path
from mod_nailong.tools.master_archive import recorded_outputs
from tools.checkpoint_request_proof import classify_returned_attempt
batch=sys.argv[1];assert re.fullmatch('[A-Za-z0-9-]+',batch)
folder=ROOT/'runtime/low-scoped-checkpoints'/batch
assert not folder.exists(),'Never replace an earlier checkpoint snapshot'
folder.mkdir(parents=True);snap=folder/'snapshot';snap.mkdir()
def git(*args,data=None):
 for attempt in range(61):
  r=subprocess.run(['git','-c','gc.auto=0','-c','maintenance.auto=false',*args],cwd=ROOT,input=data,capture_output=True,env={**os.environ,'GIT_OPTIONAL_LOCKS':'0'})
  if r.returncode and b'index.lock' in r.stderr and b'File exists' in r.stderr and attempt<60:time.sleep(0.5);continue
  break
 if r.returncode:raise RuntimeError(r.stdout.decode('utf-8','replace')+'\n'+r.stderr.decode('utf-8','replace'))
 return r.stdout
head=git('rev-parse','HEAD').decode().strip()
assert not git('diff','--cached','--name-only').strip(),'Another staged task must remain untouched'
def committed(path):return json.loads(git('show',head+':'+path))
baseline=read_json(ROOT/'runtime/resume-low-20261025/baseline-state.json')
initial=set(line[3:] for line in baseline['status'].splitlines())
priority=read_json(ROOT/'mod_nailong/data/production-priority.json')['sources']
is_low=lambda k:k in priority and not priority[k]['high_priority']
prefix='mod_nailong/data/'
oldgenerated=committed(prefix+'generated.json');current=read_json(ROOT/(prefix+'generated.json'))
generated=copy.deepcopy(oldgenerated)
changed_keys={k for k,r in current['portraits'].items() if is_low(k) and r!=oldgenerated['portraits'].get(k)}
for key in changed_keys:generated['portraits'][key]=current['portraits'][key]
assert all(not priority[k]['high_priority'] for k in changed_keys)
write_json(snap/(prefix+'generated.json'),generated)
paths=set();journals={}
for key in priority:
 if not is_low(key):continue
 path=prefix+'generation-requests/'+key+'.json';real=ROOT/path
 if not real.exists():continue
 body=real.read_bytes()
 try:old=git('show',head+':'+path)
 except RuntimeError:old=None
 if body==old:continue
 assert path not in initial,'Do not stage an initial dirty journal'
 journals[key]=json.loads(body);target=snap/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(body);paths.add(path)
 for a in journals[key]['attempts']:
  if a.get('prompt_file'):paths.add(a['prompt_file'])
for key in list(changed_keys):
 row=current['portraits'][key]
 journal=journals.get(key)
 if journal is None:
  p=ROOT/(prefix+'generation-requests/'+key+'.json')
  journal=read_json(p) if p.is_file() else {'attempts':[]}
 if not row.get('request_journal') or not any(a.get('fullsize_sha256')==row['generated_fullsize_sha256'] for a in journal['attempts']):
  changed_keys.remove(key)
  if key in oldgenerated['portraits']:generated['portraits'][key]=oldgenerated['portraits'][key]
  else:generated['portraits'].pop(key,None)
write_json(snap/(prefix+'generated.json'),generated)
for key in changed_keys:
 paths.add(current['portraits'][key]['image'])
for name,field in [('image-retry-queue.json','sources')]:
 old=committed(prefix+name);cur=read_json(ROOT/(prefix+name));merged=copy.deepcopy(old)
 for k,v in cur[field].items():
  if is_low(k) and v!=old[field].get(k):merged[field][k]=v
 if merged!=old:write_json(snap/(prefix+name),merged);paths.add(prefix+name)
old=committed(prefix+'generation-failures.json');cur=read_json(ROOT/(prefix+'generation-failures.json'));merged=copy.deepcopy(old)
old_ids={json.dumps(a,sort_keys=True) for a in old['attempts']}
for a in cur['attempts']:
 if is_low(a['source_sha256']) and json.dumps(a,sort_keys=True) not in old_ids:merged['attempts'].append(a)
for p in cur.get('held_source_paths',[]):
 if p not in old.get('held_source_paths',[]) and any(priority[k].get('high_priority') is False and any(f['source_sha256']==k and f['source_path']==p for f in cur['attempts']) for k in changed_keys|set(journals)):
  merged.setdefault('held_source_paths',[]).append(p)
if merged!=old:write_json(snap/(prefix+'generation-failures.json'),merged);paths.add(prefix+'generation-failures.json')
changed=set(git('diff','--name-only').decode('utf-8').splitlines())|set(git('ls-files','--others','--exclude-standard').decode('utf-8').splitlines())
allowed_dirs=('production-window-timings/','production-preparation-receipts/','production-ready-refills/','production-fresh-source-observations/','production-fresh-observation-completions/','production-priority-dispatches/','production-review-slot-completions/','resumed-review-evidence/')
for path in changed-initial:
 if not path.startswith(prefix):continue
 rel=path[len(prefix):]
 if rel.startswith(allowed_dirs) or re.fullmatch('resumed-20261024-rolling[ab][0-9]+-agent-review.json',rel) or (rel.startswith('resumed-fresh-observed-') and rel.endswith('-prepared.json')):
  paths.add(path)
remote_proof=ROOT/(prefix+'fullsize-git-checkpoint.json')
if remote_proof.is_file():
 proof=read_json(remote_proof)
 if any(read_json(p).get('commit')==proof.get('commit') for p in (ROOT/'runtime/low-scoped-checkpoints').glob('*/receipt.json')):
  paths.add(prefix+'fullsize-git-checkpoint.json')
for path in sorted(paths):
 if (snap/path).exists():continue
 real=ROOT/path;assert real.is_file(),path
 target=snap/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(real.read_bytes())
index=committed(prefix+'fullsize-files.json');expected,_,provenance=recorded_outputs(snap/'mod_nailong')
incremental='--incremental' in sys.argv[2:]
digests=(expected-set(index['outputs'])) if incremental else (set(index['outputs'])|expected)
masters=[]
for digest in sorted(digests):
 source=ROOT/master_path(digest);assert source.is_file(),str(source)
 if digest in index['outputs']:
  e=index['outputs'][digest];size=e['size'];mode=e['mode'];refs=e['provenance']
 else:
  with Image.open(source) as image:size=list(image.size);mode=image.mode
  refs=provenance[digest]
 masters.append({'path':str(source),'sha256':digest,'bytes':source.stat().st_size,'size':size,'mode':mode,'provenance':refs})
# This is a bounded metadata snapshot. PNG targets are same-volume hardlinks;
# every byte still passes the existing sync-git SHA256/PNG validator once.
synced=sync_git({'current_masters_missing':[],'historical_fullsize_sha_missing':[],'masters':masters},root=snap)
if incremental:
 synced['outputs']={**index['outputs'],**synced['outputs']}
 synced['count']=len(synced['outputs']);synced['original_png_bytes']=sum(e['bytes'] for e in synced['outputs'].values())
 write_json(snap/(prefix+'fullsize-files.json'),synced)
paths.add(prefix+'generated.json');paths.add(prefix+'fullsize-files.json')
new_digests=set(synced['outputs'])-set(index['outputs'])
paths|={master_path(d) for d in new_digests}
inherited=[]
for key,journal in journals.items():
 try:parent_attempts=committed(prefix+'generation-requests/'+key+'.json')['attempts']
 except RuntimeError:parent_attempts=[]
 latest=journal['attempts'][-1]
 for a in journal['attempts']:
  assert file_sha256(ROOT/a['prompt_file'])==a['prompt_sha256']
  assert (ROOT/a['prompt_file']).read_text(encoding='utf-8')==a['prompt']
  verification=a.get('actual_request_verification')
  if verification and a['status']!='prepared':
   ledger=read_json(ROOT/f'runtime/production-queue/dispatch/{key}-{a["number"]:03}.json')
   actual_path=Path(ledger['actual_request_snapshot_file']);actual=read_json(actual_path)
   assert file_sha256(actual_path)==verification['actual_request_snapshot_sha256']==ledger['actual_request_snapshot_sha256']
   assert actual['prompt']==a['prompt'] and actual['transparent']==verification['transparent_background']
   assert [file_sha256(Path(p)) for p in actual['references']]==verification['input_sha256']==ledger['input_sha256']
   if a.get('fullsize_sha256'):
    assert ledger['status']=='returned_image' and file_sha256(Path(ledger['returned_image']))==a['fullsize_sha256']==ledger['returned_image_sha256']
   proof_path=prefix+f'production-call-proofs/{key}-{a["number"]:03}-{verification["actual_request_snapshot_sha256"][:12]}.json'
   proof={'machine_id':machine_id(),'actual_request_verification':verification,'actual_payload':actual,'dispatch_ledger':ledger,'scope':'Original pre-call payload and actual return ledger copied into this checkpoint after generation; original reliable UTC and hashes retained. No image replay or retroactive pre-call claim.'}
   if not (ROOT/proof_path).exists():write_json(ROOT/proof_path,proof)
   else:assert read_json(ROOT/proof_path)==proof
   write_json(snap/proof_path,proof);paths.add(proof_path)
  if a.get('fullsize_sha256'):
   boundary=classify_returned_attempt(a,parent_attempts,index['outputs'],machine_id())
   if boundary=='unchanged_committed_legacy_return':inherited.append({'source_sha256':key,'attempt':a['number'],'fullsize_sha256':a['fullsize_sha256'],'boundary':boundary})
if inherited:
 path=prefix+'production-checkpoint-inherited-evidence/'+batch+'.json'
 write_json(snap/path,{'machine_id':machine_id(),'observed_at_utc':utc_now(),'parent_commit':head,'inherited':inherited,'scope':'These exact entire attempt records and original PNG index entries were already committed in the immutable parent. No new pre-call proof is claimed for these legacy returns. Every new or changed returned attempt still requires modern pre-call proof. Existing PNGs are inherited from the parent, not freshly remotely read by this classification.'});paths.add(path)
assert git('rev-parse','HEAD').decode().strip()==head,'Another commit advanced; preserve this snapshot and reconcile before staging'
write_json(folder/'prepared-snapshot.json',{'parent_commit':head,'paths':sorted(paths),'new_original_PNGs':len(new_digests),'snapshot':snap.relative_to(ROOT).as_posix()})
ordered=sorted(paths)
assert all((snap/path).is_file() and '\n' not in path and '\r' not in path for path in ordered)
source_paths=''.join((snap/path).as_posix()+'\n' for path in ordered).encode('utf-8')
oids=git('hash-object','-w','--stdin-paths',data=source_paths).decode().splitlines()
assert len(oids)==len(ordered)
git('update-index','--index-info',data=''.join('100644 '+oid+'\t'+path+'\n' for path,oid in zip(ordered,oids)).encode('utf-8'))
git('diff','--cached','--check')
assert set(git('diff','--cached','--name-only').decode('utf-8').splitlines())<=paths,'Other staged work appeared; do not commit it'
message=('Preserve resumed LOW portraits and exact built-in requests\n').encode()
git('commit','-F','-',data=message)
commit=git('rev-parse','HEAD').decode().strip()
receipt={'machine_id':machine_id(),'completed_at_utc':utc_now(),'batch':batch,'parent_commit':head,'commit':commit,'generated_LOW_rows_changed':len(changed_keys),'LOW_journals_changed':len(journals),'new_original_PNGs':len(new_digests),'new_original_bytes':sum(synced['outputs'][d]['bytes'] for d in new_digests),'original_index_count':synced['count'],'paths':sorted(paths),'snapshot':snap.relative_to(ROOT).as_posix(),'baseline':baseline['HEAD'],'excluded_initial_dirty_paths':sorted(initial),'status':'committed_push_pending','local_original_validation':'New PNGs fully verified with sync-git; existing index retained from immutable parent Git commit, not claimed freshly read' if incremental else 'Every indexed original freshly hashed and PNG-verified with sync-git','scope':'Snapshot commit of this LOW production only. Initial colleagues records and source code left unstaged and intact. Snapshot PNGs are same-volume hardlinks, not re-encoded or duplicate payloads. No full-library game build/export and no game/Steam claim.'}
write_json(folder/'receipt.json',receipt)
print(json.dumps({k:v for k,v in receipt.items() if k not in {'paths','excluded_initial_dirty_paths'}},ensure_ascii=True))
